/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const playbookCardProperties = api.data.playbook_activity_ui.playbookCardProperties;
  const activityStatus = playbookCardProperties && playbookCardProperties.activityState.value;
	return  activityStatus == 'COMPLETE' || !api.state.plugins.length;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    var inActivePluginsCount = api.state.inActivePluginsCount;
    return inActivePluginsCount == 0;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.state.cicdResponse && Object.keys(api.state.cicdResponse).length || !api.state.installPlugins.length;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    var inActivePluginsCount = api.state.inActivePluginsCount;
    return inActivePluginsCount != 0;
}

